#!/usr/bin/env python3
# Generates the large-tile (128 rows x 128 tokens) prompt-reading kernels for every non-NQ4 weight format from one skeleton.
import sys
HEAD = r'''// nexus/src/gpu/shaders/@NAME@.comp -- @DESC@, prompt reading (matrix x many tokens), large-tile kernel
// GENERATED by tools/gen_mm_shaders.py from one skeleton (same design as mat_mat_nq4_g64_big.comp):
//   Y[token, row] = dot(W[row, :], X[token, :])
// A workgroup of 256 threads computes a 128-row x 128-token tile of Y; every thread owns an 8 x 8 register tile (64 accumulators).  The columns are
// walked 32 at a time; the next step's global loads are issued BEFORE the current step's maths so memory latency overlaps with the multiply-adds.
// Weights are decoded to float in shared memory.  Columns beyond in_cols read as zero, so any in_cols that is a multiple of 4 works.
// DISPATCH: groups = (ceil(out_rows/128), ceil(n_tokens/128)).  Pipeline::mm_tile_rows / mm_tile_toks must be 128 / 128.
// Push constants: out_rows, in_cols, n_blocks_per_row, n_tokens   (n_blocks_per_row counts @BLKDESC@)

#version 450
#extension GL_EXT_control_flow_attributes : enable
layout(local_size_x = 256) in;

layout(set = 0, binding = 0) readonly buffer WeightBuf  { uint  W[];  };
layout(set = 0, binding = 1) readonly buffer InputBuf   { vec4  x4[]; };
layout(set = 0, binding = 2) writeonly buffer OutputBuf { float y[];  };

layout(push_constant) uniform PC {
    uint out_rows;
    uint in_cols;
    uint n_blocks_per_row;
    uint n_tokens;
} pc;

const uint BM  = 128u;
const uint BN  = 128u;
const uint BK  = 32u;
const uint SPB = @SPB@u;            // 32-column steps per weight block
const uint BLK_BYTES = @BLKBYTES@u;

shared vec4 Ws4[BK * 32u];   // [k][row/4]  decoded weights
shared vec4 Xs4[BK * 32u];   // [k][tok/4]  inputs

uint last_word;
float f16_to_f32(uint h){ return unpackHalf2x16(h & 0xFFFFu).x; }
uint ld32(uint o) {                 // 4 bytes at even byte offset o (clamped to the end of the matrix)
    const uint w = o >> 2u;
    const uint a = W[min(w, last_word)];
    if ((o & 2u) == 0u) return a;
    return (a >> 16u) | (W[min(w + 1u, last_word)] << 16u);
}
uint ld8(uint o) { return (W[min(o >> 2u, last_word)] >> ((o & 3u) * 8u)) & 255u; }

// register-resident prefetch of the next step
uint  p_w[@NWP1@];
uint  p_h[4];
float p_a, p_b;
uint  p_ss;
vec4  p_x[4];

void load_step(uint s, uint row, uint tok, uint half_) {
    const uint nb = pc.n_blocks_per_row;
    const uint g  = s / SPB;
    const uint ss = s % SPB;
    p_ss = ss; p_a = 0.0; p_b = 0.0;
    [[unroll]] for (uint i = 0u; i < @NWP1@u; ++i) p_w[i] = 0u;
    [[unroll]] for (uint i = 0u; i < 4u; ++i) p_h[i] = 0u;
    if (row < pc.out_rows) {
@LOAD@
    }
    const uint c = s * BK + half_ * 16u;
    if (tok < pc.n_tokens && c < pc.in_cols) {
        const uint base = (tok * pc.in_cols + c) >> 2u;
        p_x[0] = x4[base]; p_x[1] = x4[base + 1u]; p_x[2] = x4[base + 2u]; p_x[3] = x4[base + 3u];
    } else {
        p_x[0] = vec4(0.0); p_x[1] = vec4(0.0); p_x[2] = vec4(0.0); p_x[3] = vec4(0.0);
    }
}

float decode_w(uint k) {            // weight k (0..15) of this thread's slice of the current step
@DECODE@
}

void main() {
    const uint tid  = gl_LocalInvocationID.x;
    const uint row0 = gl_WorkGroupID.x * BM;
    const uint tok0 = gl_WorkGroupID.y * BN;
    last_word = (pc.out_rows * pc.n_blocks_per_row * BLK_BYTES + 3u) / 4u - 1u;

    const uint ld_item = tid >> 1u;
    const uint ld_half = tid & 1u;
    const uint ld_row  = row0 + ld_item;
    const uint ld_tok  = tok0 + ld_item;

    const uint tx = tid & 15u;
    const uint ty = tid >> 4u;

    float acc[8][8];
    [[unroll]] for (uint i = 0u; i < 8u; ++i) [[unroll]] for (uint j = 0u; j < 8u; ++j) acc[i][j] = 0.0;

    const uint steps = pc.n_blocks_per_row * SPB;
    load_step(0u, ld_row, ld_tok, ld_half);

    for (uint s = 0u; s < steps; ++s) {
        {
            [[unroll]] for (uint k = 0u; k < 16u; ++k)
                Ws4[(ld_half * 16u + k) * 32u + (ld_item >> 2u)][ld_item & 3u] = decode_w(k);
            [[unroll]] for (uint i = 0u; i < 4u; ++i)
                [[unroll]] for (uint c = 0u; c < 4u; ++c)
                    Xs4[(ld_half * 16u + i * 4u + c) * 32u + (ld_item >> 2u)][ld_item & 3u] = p_x[i][c];
        }
        barrier();

        if (s + 1u < steps) load_step(s + 1u, ld_row, ld_tok, ld_half);

        for (uint k = 0u; k < BK; ++k) {
            const vec4 wa = Ws4[k * 32u + tx];
            const vec4 wb = Ws4[k * 32u + 16u + tx];
            const vec4 xa = Xs4[k * 32u + ty];
            const vec4 xb = Xs4[k * 32u + 16u + ty];
            const float w[8] = float[8](wa.x, wa.y, wa.z, wa.w, wb.x, wb.y, wb.z, wb.w);
            const float x[8] = float[8](xa.x, xa.y, xa.z, xa.w, xb.x, xb.y, xb.z, xb.w);
            [[unroll]] for (uint i = 0u; i < 8u; ++i)
                [[unroll]] for (uint j = 0u; j < 8u; ++j)
                    acc[i][j] += w[i] * x[j];
        }
        barrier();
    }

    [[unroll]] for (uint j = 0u; j < 8u; ++j) {
        const uint tok = tok0 + ((j < 4u) ? (ty * 4u + j) : (64u + ty * 4u + (j - 4u)));
        if (tok >= pc.n_tokens) continue;
        [[unroll]] for (uint i = 0u; i < 8u; ++i) {
            const uint r = row0 + ((i < 4u) ? (tx * 4u + i) : (64u + tx * 4u + (i - 4u)));
            if (r < pc.out_rows) y[tok * pc.out_rows + r] = acc[i][j];
        }
    }
}
'''

Q8 = dict(DESC='GGUF Q8_0', BLKDESC='blocks of 32 weights (in_cols/32)', SPB=1, BLKBYTES=34, NW=4,
LOAD='''        const uint rec = (row * nb + g) * 34u;
        p_a = f16_to_f32(W[rec >> 2u] >> ((rec & 2u) * 8u));
        const uint o = rec + 2u + half_ * 16u;
        [[unroll]] for (uint i = 0u; i < 4u; ++i) p_w[i] = ld32(o + 4u * i);''',
DECODE='''    return float(int(p_w[k >> 2u] << (24u - 8u * (k & 3u))) >> 24) * p_a;''')

Q4K = dict(DESC='GGUF Q4_K', BLKDESC='superblocks of 256 weights (in_cols/256)', SPB=8, BLKBYTES=144, NW=4,
LOAD='''        const uint bw = (row * nb + g) * 36u;
        const uint w0 = W[bw];
        const uint s0 = W[bw + 1u], s1 = W[bw + 2u], s2 = W[bw + 3u];
        float sc, mn;
        if (ss < 4u) { sc = float((s0 >> (8u * ss)) & 63u); mn = float((s1 >> (8u * ss)) & 63u); }
        else { const uint a = ss - 4u;
               sc = float(((s2 >> (8u * a)) & 15u) | ((((s0 >> (8u * a)) >> 6u) & 3u) << 4u));
               mn = float(((s2 >> (8u * a + 4u)) & 15u) | ((((s1 >> (8u * a)) >> 6u) & 3u) << 4u)); }
        p_a = f16_to_f32(w0) * sc; p_b = f16_to_f32(w0 >> 16u) * mn;
        const uint qo = bw + 4u + (ss >> 1u) * 8u + half_ * 4u;
        [[unroll]] for (uint i = 0u; i < 4u; ++i) p_w[i] = W[qo + i];''',
DECODE='''    return float((p_w[k >> 2u] >> ((k & 3u) * 8u + 4u * (p_ss & 1u))) & 15u) * p_a - p_b;''')

Q5K = dict(DESC='GGUF Q5_K', BLKDESC='superblocks of 256 weights (in_cols/256)', SPB=8, BLKBYTES=176, NW=4,
LOAD='''        const uint bw = (row * nb + g) * 44u;
        const uint w0 = W[bw];
        const uint s0 = W[bw + 1u], s1 = W[bw + 2u], s2 = W[bw + 3u];
        float sc, mn;
        if (ss < 4u) { sc = float((s0 >> (8u * ss)) & 63u); mn = float((s1 >> (8u * ss)) & 63u); }
        else { const uint a = ss - 4u;
               sc = float(((s2 >> (8u * a)) & 15u) | ((((s0 >> (8u * a)) >> 6u) & 3u) << 4u));
               mn = float(((s2 >> (8u * a + 4u)) & 15u) | ((((s1 >> (8u * a)) >> 6u) & 3u) << 4u)); }
        p_a = f16_to_f32(w0) * sc; p_b = f16_to_f32(w0 >> 16u) * mn;
        const uint qo = bw + 12u + (ss >> 1u) * 8u + half_ * 4u;
        const uint ho = bw + 4u + half_ * 4u;
        [[unroll]] for (uint i = 0u; i < 4u; ++i) { p_w[i] = W[qo + i]; p_h[i] = W[ho + i]; }''',
DECODE='''    const uint nib = (p_w[k >> 2u] >> ((k & 3u) * 8u + 4u * (p_ss & 1u))) & 15u;
    const uint hb  = (p_h[k >> 2u] >> ((k & 3u) * 8u + p_ss)) & 1u;
    return float(nib + 16u * hb) * p_a - p_b;''')

Q6K = dict(DESC='GGUF Q6_K', BLKDESC='superblocks of 256 weights (in_cols/256)', SPB=8, BLKBYTES=210, NW=4,
LOAD='''        const uint bo = (row * nb + g) * 210u;
        const uint n = ss >> 2u, p = ss & 3u;
        const uint qlo = bo + n * 64u + (p & 1u) * 32u + half_ * 16u;
        const uint qho = bo + 128u + n * 32u + half_ * 16u;
        [[unroll]] for (uint i = 0u; i < 4u; ++i) { p_w[i] = ld32(qlo + 4u * i); p_h[i] = ld32(qho + 4u * i); }
        const float d  = f16_to_f32(ld8(bo + 208u) | (ld8(bo + 209u) << 8u));
        const int   sb = int(ld8(bo + 192u + 8u * n + half_ + 2u * p) << 24u) >> 24;
        p_a = d * float(sb);''',
DECODE='''    const uint p = p_ss & 3u;
    const uint nib = (p_w[k >> 2u] >> ((k & 3u) * 8u + 4u * (p >> 1u))) & 15u;
    const uint hi2 = (p_h[k >> 2u] >> ((k & 3u) * 8u + 2u * p)) & 3u;
    return p_a * float(int(nib | (hi2 << 4u)) - 32);''')


Q2K = dict(DESC='GGUF Q2_K', BLKDESC='superblocks of 256 weights (in_cols/256)', SPB=8, BLKBYTES=84, NW=4,
LOAD='''        const uint bw = (row * nb + g) * 21u;
        const uint n = ss >> 2u;
        const uint idx = 2u * ss + half_;                                     // sub-block scale byte
        const uint scb = (W[bw + (idx >> 2u)] >> ((idx & 3u) * 8u)) & 255u;
        const uint dd  = W[bw + 20u];
        p_a = f16_to_f32(dd) * float(scb & 15u); p_b = f16_to_f32(dd >> 16u) * float(scb >> 4u);
        [[unroll]] for (uint i = 0u; i < 4u; ++i) p_w[i] = W[bw + 4u + 8u * n + 4u * half_ + i];''',
DECODE='''    return float((p_w[k >> 2u] >> ((k & 3u) * 8u + 2u * (p_ss & 3u))) & 3u) * p_a - p_b;''')

Q3K = dict(DESC='GGUF Q3_K', BLKDESC='superblocks of 256 weights (in_cols/256)', SPB=8, BLKBYTES=110, NW=4,
LOAD='''        const uint bo = (row * nb + g) * 110u;
        const uint n = ss >> 2u;
        const uint idx = 2u * ss + half_;                                     // sub-block scale index 0..15
        const uint lo = (idx < 8u) ? (ld8(bo + 96u + idx) & 15u) : (ld8(bo + 96u + idx - 8u) >> 4u);
        const uint hi = (ld8(bo + 104u + (idx & 3u)) >> (2u * (idx >> 2u))) & 3u;
        const float d = f16_to_f32(ld8(bo + 108u) | (ld8(bo + 109u) << 8u));
        p_a = d * float(int(lo | (hi << 4u)) - 32);
        [[unroll]] for (uint i = 0u; i < 4u; ++i) { p_w[i] = ld32(bo + 32u + 32u * n + 16u * half_ + 4u * i); p_h[i] = ld32(bo + 16u * half_ + 4u * i); }''',
DECODE='''    const uint q2 = (p_w[k >> 2u] >> ((k & 3u) * 8u + 2u * (p_ss & 3u))) & 3u;
    const uint hb = (p_h[k >> 2u] >> ((k & 3u) * 8u + p_ss)) & 1u;
    return p_a * float(int(q2) - ((hb != 0u) ? 0 : 4));''')

def nq(bits):
    nw = (2 * bits + 3) // 4
    rec = 2 + 8 * bits
    return dict(DESC='Nexus native NQ%d_G64' % bits, BLKDESC='groups of 64 weights (ceil(in_cols/64))', SPB=2, BLKBYTES=rec, NW=nw,
    LOAD='''        const uint rec = (row * nb + g) * %du;
        p_a = f16_to_f32(W[rec >> 2u] >> ((rec & 2u) * 8u));
        const uint o = rec + 2u + (2u * ss + half_) * %du;
        [[unroll]] for (uint i = 0u; i < %du; ++i) p_w[i] = ld32(o + 4u * i);''' % (rec, 2 * bits, nw),
    DECODE='''    const uint bit = k * %du, wi = bit >> 5u, sh = bit & 31u;
    uint v = p_w[wi] >> sh;
    if (sh + %du > 32u) v |= p_w[wi + 1u] << (32u - sh);
    return (float(v & %du) - %d.0) * p_a;''' % (bits, bits, (1 << bits) - 1, 1 << (bits - 1)))

FORMATS = {'mat_mat_q8_0': Q8, 'mat_mat_q4k': Q4K, 'mat_mat_q5k': Q5K, 'mat_mat_q6k': Q6K, 'mat_mat_q2k': Q2K, 'mat_mat_q3k': Q3K,
           'mat_mat_nq5_g64': nq(5), 'mat_mat_nq6_g64': nq(6), 'mat_mat_nq8_g64': nq(8)}

outdir = sys.argv[1] if len(sys.argv) > 1 else '.'
for name, f in FORMATS.items():
    t = HEAD
    for k, v in (('@NAME@', name), ('@DESC@', f['DESC']), ('@BLKDESC@', f['BLKDESC']), ('@SPB@', str(f['SPB'])), ('@BLKBYTES@', str(f['BLKBYTES'])),
                 ('@NWP1@', str(f['NW'] + 1)), ('@LOAD@', f['LOAD']), ('@DECODE@', f['DECODE'])):
        t = t.replace(k, v)
    open('%s/%s.comp' % (outdir, name), 'w').write(t)
print('wrote', len(FORMATS), 'shaders')
